html:
{#-
T102 — COA AMB Print Format (FoxPro GREENTECH parity) — SCHEMA-BOUND v2
App: amb_print · DocType: COA AMB · Renderer: wkhtmltopdf · Jinja standard format

Verified field bindings (PROD schema 2026-06-10):
  item_name                              → PRODUCT NAME
  batch_reference (Link Batch)           → LOT CODE; Batch.manufacturing_date → MNFR. DATE / M.D.;
                                           Batch.expiry_date → E.D.
  inci_name / cas_number                 → header sublines
  coa_quality_test_parameter             → child rows: parameter_name, specification (fallback: value),
                                           result, custom_is_title_row (L372/L373),
                                           custom_reconstituted_to_05_total_solids_solution → "*" + footnote
  shelf_life / packaging / storage_and_handling_conditions (Text Editor, HTML) → page 3
  autorizacion (Signature) → signature; T88 fallback: approved_by User.signature_image → user_image
-#}
<style>
    .coa-body { font-family: Calibri, 'Segoe UI', sans-serif; font-size: 9.5pt; color: #000; }
    .coa-header { width: 100%; margin-bottom: 4px; }
    .coa-header td { vertical-align: top; border: none !important; }
    .coa-company { text-align: center; font-size: 8.5pt; line-height: 1.25; }
    .coa-pageno { text-align: right; font-size: 8.5pt; white-space: nowrap; }
    .coa-logo { width: 95px; }
    .coa-title { text-align: center; font-size: 13pt; font-weight: bold; margin: 14px 0 6px 0; }
    .coa-subline { text-align: center; font-size: 9.5pt; margin: 2px 0; }
    .coa-identity { margin: 10px 0 14px 0; font-size: 9.5pt; }
    .coa-identity td { border: none !important; padding: 3px 0; }
    .coa-identity .lbl { width: 130px; }
    table.coa-params { width: 100%; border-collapse: collapse; margin-top: 6px; }
    table.coa-params thead th {
        border: 1px solid #000; border-left: none; border-right: none;
        text-align: left; font-weight: bold; font-size: 9.5pt; padding: 5px 6px;
    }
    table.coa-params thead th:first-child { border-left: 1px solid #000; }
    table.coa-params thead th:last-child { border-right: 1px solid #000; }
    table.coa-params td { border: none; padding: 4.5px 6px; font-size: 9.5pt; }
    .coa-titlerow td { font-weight: bold; padding-top: 8px !important; }
    .coa-footnote { font-size: 8.5pt; margin-top: 8px; }
    .coa-dates { font-size: 9.5pt; margin-top: 14px; line-height: 1.5; }
    .coa-signature img { max-height: 70px; }
    .coa-continue { text-align: center; font-size: 9pt; margin-top: 18px; }
    .coa-section-h { font-weight: bold; font-size: 9.5pt; margin: 14px 0 3px 0; }
    .coa-section-p, .coa-section-p p { font-size: 9pt; line-height: 1.35; margin: 0 0 4px 0; }
</style>

{%- set batch = frappe.db.get_value("Batch", doc.batch_reference,
        ["manufacturing_date", "expiry_date"], as_dict=True) if doc.batch_reference else None -%}

{#- T88 signature fallback chain (T90.3 doctrine, resolved against the APPROVER not the printer) -#}
{%- set sig = doc.autorizacion
        or (frappe.db.get_value("User", doc.approved_by, "signature_image") if doc.approved_by else None)
        or (frappe.db.get_value("User", doc.approved_by, "user_image") if doc.approved_by else None) -%}

{%- macro page_header() -%}
<table class="coa-header"><tr>
    <td class="coa-logo"><img src="/files/amb_logo.jpg" style="width:95px"></td>
    <td class="coa-company">
        Agromayal Botanica, S.A. de C.V.<br>
        Calle Guanacevi 245 Parque Industrial G&oacute;mez Palacio.<br>
        G&oacute;mez Palacio, Durango CP 35078<br>
        Tel. 52-871-750-0846<br>
        e-mail: info@amb-wellness.com<br>
        Web Page: www.amb-wellness.com
    </td>
    <td class="coa-pageno"></td> {#- wkhtmltopdf page numbers come from Frappe's footer html; see JSON -#}
</tr></table>
<div class="coa-title">CERTIFICATE OF ANALYSIS</div>
{% if doc.inci_name %}<div class="coa-subline">INCI NAME : {{ doc.inci_name | upper }}</div>{% endif %}
{% if doc.cas_number %}<div class="coa-subline">CAS NUMBER : {{ doc.cas_number }}</div>{% endif %}
<table class="coa-identity">
    <tr><td class="lbl">PRODUCT NAME</td><td>{{ (doc.item_name or "") | upper }}</td></tr>
    <tr><td class="lbl">LOT CODE</td><td>{{ doc.batch_reference or "" }}</td></tr>
    {% if batch and batch.manufacturing_date %}
    <tr><td class="lbl">MNFR. DATE</td><td>{{ frappe.utils.formatdate(batch.manufacturing_date, "dd/MM/yy") }}</td></tr>
    {% endif %}
</table>
{%- endmacro -%}

<div class="coa-body">
{{ page_header() }}

{%- set ns = namespace(has_footnote=false) -%}
<table class="coa-params">
    <thead>
        <tr><th style="width:38%">PARAMETER</th><th style="width:34%">SPECIFICATION</th><th style="width:28%">RESULT</th></tr>
    </thead>
    <tbody>
    {%- for row in doc.coa_quality_test_parameter %}
        {#- L373 title-row signal: explicit flag OR legacy value == "Specification" -#}
        {%- if row.custom_is_title_row or (row.value or "").strip() == "Specification" %}
        <tr class="coa-titlerow"><td colspan="3">{{ (row.parameter_name or "") | upper }}</td></tr>
        {%- else %}
        {%- set star = "*" if row.custom_reconstituted_to_05_total_solids_solution else "" %}
        {%- if star %}{% set ns.has_footnote = true %}{% endif %}
        <tr>
            <td>{{ (row.parameter_name or "") | upper }}{{ star }}</td>
            <td>{{ ((row.specification or row.value or "") | upper).strip() }}</td>
            <td>{{ ((row.result or "") | upper).strip() }}</td>
        </tr>
        {%- endif %}
    {%- endfor %}
    </tbody>
</table>

{% if ns.has_footnote %}<div class="coa-footnote">*RECONSTITUTED TO 0.5% TOTAL SOLIDS SOLUTION.</div>{% endif %}

{% if batch %}
<div class="coa-dates">
    {% if batch.manufacturing_date %}M.D. {{ frappe.utils.formatdate(batch.manufacturing_date, "dd/MM/yy") }}<br>{% endif %}
    {% if batch.expiry_date %}E.D. {{ frappe.utils.formatdate(batch.expiry_date, "dd/MM/yy") }}{% endif %}
</div>
{% endif %}

{% if sig %}
<div class="coa-signature"><img src="{{ sig }}"></div>
{% endif %}

{%- if doc.shelf_life or doc.packaging or doc.storage_and_handling_conditions %}
<div style="page-break-before: always;"></div>
{{ page_header() }}
{% if doc.shelf_life %}
<div class="coa-section-h">SHELF LIFE:</div><div class="coa-section-p">{{ doc.shelf_life | safe }}</div>
{% endif %}
{% if doc.packaging %}
<div class="coa-section-h">PACKAGING:</div><div class="coa-section-p">{{ doc.packaging | safe }}</div>
{% endif %}
{% if doc.storage_and_handling_conditions %}
<div class="coa-section-h">STORAGE AND HANDLING CONDITIONS:</div>
<div class="coa-section-p">{{ doc.storage_and_handling_conditions | safe }}</div>
{% endif %}
{%- endif %}
</div>
